INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES
(7201,1,'psiquiatria','evolucao','Evolução ambulatorial em saúde mental','Paciente retorna em acompanhamento, referindo [sintomas principais]. Relata adesão [boa/parcial/baixa] ao tratamento, com [efeitos/benefícios]. Ao exame psíquico, apresenta [humor/afeto], pensamento [descrição], juízo crítico [descrição]. Mantida/ajustada conduta com [medicação/intervenção], orientado sobre sinais de alerta e retorno em [prazo].','sintomas principais, adesão, exame psíquico, conduta','psiquiatria, evolução, retorno',1,204,204,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7202,1,'pediatria','orientacao','Orientações domiciliares para febre infantil','Orientado responsável quanto à hidratação frequente, controle térmico conforme peso/idade, repouso relativo e observação de diurese. Retornar imediatamente em caso de prostração, dificuldade respiratória, recusa alimentar persistente, convulsão, sonolência excessiva ou febre prolongada.','hidratação, sinais de alarme, retorno','pediatria, orientação, febre',1,205,205,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7203,1,'ginecologia_obstetricia','retorno','Retorno de pré-natal habitual','Gestante em seguimento de pré-natal, com boa aceitação alimentar e movimentação fetal presente. Mantidas orientações sobre sinais de alerta, suplementação prescrita e calendário de exames. Próximo retorno programado para [data/período].','idade gestacional, sinais de alerta, próximo retorno','pré-natal, obstetrícia, retorno',1,206,206,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7204,1,'cardiologia','laudo','Resumo para risco cardiovascular','Paciente em acompanhamento cardiológico por [motivo]. Apresenta fatores de risco: [fatores]. Exames prévios demonstram [resultados]. Mantido plano com foco em metas pressóricas, controle lipídico, atividade física e reavaliação com [exames/retorno].','motivo, fatores de risco, exames, plano','cardiologia, laudo, risco',1,208,208,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7205,1,'neurologia','checklist','Checklist de retorno para cefaleia','- Atualizar frequência e intensidade da dor\n- Rever gatilhos e medicações usadas\n- Confirmar presença de aura/sinais neurológicos\n- Conferir exames solicitados\n- Reforçar sinais de alarme e plano de seguimento','frequência, intensidade, gatilhos, exames','neurologia, cefaleia, checklist',1,210,210,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7289,1,'medico','anamnese','Anamnese clínica geral inicial','Queixa principal: [descrição]. História da doença atual: [início, duração, evolução e sintomas associados]. Antecedentes pessoais e familiares: [descrição]. Alergias e medicamentos em uso: [descrição]. Hábitos e contexto social: [descrição]. Sinais vitais e exame físico: [achados]. Hipóteses diagnósticas: [avaliação]. Plano individualizado: [investigação, conduta e retorno].','queixa, história atual, antecedentes, alergias, medicamentos, exame físico, avaliação, plano','clínica médica, anamnese, atendimento inicial',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7207,1,'dentista','checklist','Checklist de avaliação odontológica inicial','- Revisar queixa principal e dor\n- Inspecionar biofilme, gengiva e restaurações prévias\n- Avaliar necessidade radiográfica\n- Registrar planejamento imediato e retorno','dor, higiene, radiografia, plano','odontologia, checklist, avaliação inicial',1,202,202,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7208,1,'psicologia','evolucao','Evolução breve de psicoterapia','Sessão dedicada a [tema central], com acolhimento de [emoções/reações]. Intervenções realizadas: [intervenções]. Resposta do paciente: [resposta]. Tarefa/combinação para próxima sessão: [tarefa].','tema central, intervenções, resposta, tarefa','psicologia, evolução, sessão',1,203,203,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7209,1,'psiquiatria','retorno','Retorno psiquiátrico de estabilização','Paciente retorna referindo [sintomas], adesão [boa/parcial/baixa] ao tratamento e [efeitos colaterais/benefícios]. Avaliado risco atual, sono, apetite e funcionalidade. Mantida/ajustada conduta com retorno em [prazo].','sintomas, adesão, risco, sono, funcionalidade','psiquiatria, retorno, estabilização',1,204,204,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7210,1,'pediatria','checklist','Checklist de puericultura','- Atualizar peso, estatura e desenvolvimento\n- Revisar alimentação, sono e eliminação\n- Conferir vacinação\n- Orientar sinais de alerta e próximo retorno','crescimento, alimentação, vacinação, retorno','pediatria, puericultura, checklist',1,205,205,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7211,1,'ginecologia_obstetricia','orientacao','Orientações para rotina ginecológica / pré-natal','Orientada quanto a sinais de alerta, adesão aos exames preventivos, suplementação quando indicada e retorno se [sintoma]. Manter acompanhamento periódico e hábitos saudáveis.','sinais de alerta, exames, suplementação, retorno','ginecologia, obstetrícia, orientação',1,206,206,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7212,1,'ortopedia_traumatologia','evolucao','Evolução ortopédica por dor mecânica','Paciente em seguimento por [dor/lesão], com intensidade [escala]. Exame focal demonstra [achados]. Mantidas orientações de proteção articular, analgesia e reabilitação com retorno em [prazo].','dor, exame focal, analgesia, reabilitação','ortopedia, evolução, dor',1,207,207,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7213,1,'cardiologia','orientacao','Orientações de controle pressórico domiciliar','Paciente orientado a registrar pressão arterial em horários padronizados, manter uso correto das medicações, reduzir sal, manter atividade física compatível e retornar com diário pressórico e exames.','pressão arterial, medicação, dieta, atividade física','cardiologia, orientação, hipertensão',1,208,208,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7214,1,'oftalmologia','laudo','Resumo oftalmológico ambulatorial','Paciente com [queixa visual], acuidade [achado], superfície ocular [descrição] e hipótese de [diagnóstico]. Indicada correção óptica/lubrificação/investigação complementar com retorno em [prazo].','queixa visual, acuidade, hipótese, retorno','oftalmologia, laudo, ambulatório',1,209,209,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7215,1,'neurologia','retorno','Retorno neurológico para cefaleia e sintomas sensitivos','Paciente relata [frequência] de cefaleia, presença/ausência de aura e [sintomas associados]. Exame neurológico atual [achados]. Reforçado diário de sintomas, ajuste terapêutico e sinais de urgência.','cefaleia, aura, sintomas associados, exame neurológico','neurologia, retorno, cefaleia',1,210,210,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7216,1,'medico','laudo','Modelo de solicitação e revisão de exames laboratoriais','Solicitados/revistos os seguintes exames: [hemograma], [glicemia], [perfil lipídico], [função renal], [função hepática] e [outros]. Indicação clínica: [motivo]. Resultados principais: [achados]. Conduta após análise: [conduta], com retorno em [prazo].','motivo, exames solicitados, achados, conduta, retorno','medico, exames, laboratório, laudo',1,201,201,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7217,1,'dentista','laudo','Modelo de exames complementares odontológicos','Avaliação odontológica com necessidade de exames complementares. Solicitar/revisar: [radiografia periapical], [panorâmica], [interproximal], [tomografia] e [fotografia clínica]. Indicação: [suspeita clínica]. Achados relevantes: [achados]. Planejamento proposto: [plano terapêutico].','radiografia, tomografia, achados, plano terapêutico','odontologia, exames, radiografia, laudo',1,202,202,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7218,1,'psicologia','laudo','Modelo de devolutiva de avaliação psicológica / escalas','Realizada avaliação psicológica com uso de [instrumentos/escala], observando [contexto de aplicação]. Resultados sugerem [síntese clínica], com indicadores em [faixa/classificação]. Recomenda-se [encaminhamento/intervenção], mantendo acompanhamento e reavaliação em [prazo].','instrumentos, contexto, síntese clínica, classificação, recomendação','psicologia, avaliação, escala, devolutiva',1,203,203,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7219,1,'psiquiatria','laudo','Modelo de solicitação de exames para seguimento psicofarmacológico','Paciente em uso de [medicação] com indicação de solicitar/revisar [hemograma], [TSH], [função hepática], [função renal], [ECG] e [outros] conforme perfil clínico. Objetivo: monitorar [segurança/efeitos adversos/diagnóstico diferencial]. Resultados: [achados]. Conduta: [ajuste terapêutico/seguimento].','medicação, exames, segurança, achados, ajuste terapêutico','psiquiatria, exames, monitorização, laudo',1,204,204,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7220,1,'pediatria','laudo','Modelo de solicitação e revisão de exames pediátricos','Paciente pediátrico em investigação de [quadro clínico]. Solicitar/revisar: [hemograma], [PCR], [urina], [teste viral], [imagem] e [outros]. Sinais clínicos associados: [achados]. Interpretação inicial: [síntese]. Orientações ao responsável e retorno em [prazo].','quadro clínico, exames, achados, interpretação, retorno','pediatria, exames, investigação, laudo',1,205,205,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7221,1,'ginecologia_obstetricia','laudo','Modelo de exames preventivos / pré-natal','Solicitados/revistos exames de [citologia oncótica], [USG], [sorologias], [tipagem/Rh], [glicemia], [urocultura] e [outros]. Indicação: [rotina ginecológica/pré-natal/queixa]. Resultados principais: [achados]. Conduta e seguimento: [conduta], com retorno em [prazo].','citologia, ultrassom, sorologias, achados, conduta','ginecologia, obstetrícia, exames, pré-natal',1,206,206,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7222,1,'ortopedia_traumatologia','laudo','Modelo de imagem osteomuscular e correlação clínica','Paciente com [dor/trauma/limitação]. Solicitar/revisar [raio-X], [ultrassom], [ressonância] ou [tomografia] da região [local]. Achados de imagem: [achados]. Correlação clínica: [hipótese]. Plano de tratamento: [analgesia, fisioterapia, imobilização ou cirurgia], com reavaliação em [prazo].','local, exame de imagem, achados, hipótese, tratamento','ortopedia, exames, imagem, laudo',1,207,207,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7223,1,'cardiologia','laudo','Modelo de revisão de exames cardiovasculares','Revisados os exames [ECG], [ecocardiograma], [MAPA/Holter], [teste ergométrico] e [laboratoriais]. Principais achados: [achados]. Estratificação de risco: [baixo/moderado/alto]. Conduta definida: [ajuste medicamentoso, exames adicionais, retorno], com seguimento em [prazo].','ECG, ecocardiograma, risco, achados, conduta','cardiologia, exames, ECG, ecocardiograma',1,208,208,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7224,1,'oftalmologia','laudo','Modelo de avaliação e exames oftalmológicos','Paciente com [queixa visual]. Realizados/solicitados [acuidade visual], [refração], [tonometria], [fundoscopia], [biomicroscopia], [campimetria] e [outros]. Achados principais: [achados]. Impressão diagnóstica: [hipótese]. Conduta: [correção óptica/tratamento/investigação], com retorno em [prazo].','acuidade visual, tonometria, fundoscopia, achados, conduta','oftalmologia, exames, refração, laudo',1,209,209,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7225,1,'neurologia','laudo','Modelo de exames neurológicos complementares','Paciente em investigação de [cefaleia, crise, déficit, tontura ou parestesia]. Solicitar/revisar [RM], [TC], [EEG], [ENMG], [doppler] e [outros] conforme quadro. Achados: [achados]. Correlação clínica: [hipótese diagnóstica]. Plano: [seguimento/encaminhamento/ajuste terapêutico], com retorno em [prazo].','quadro neurológico, RM, EEG, achados, hipótese, plano','neurologia, exames, imagem, EEG, laudo',1,210,210,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7227,1,'psiquiatria','anamnese','Anamnese psiquiátrica inicial','Paciente em primeira avaliação psiquiátrica, relatando [queixa principal], com início em [período] e impacto em [sono, apetite, trabalho, vínculos]. Antecedentes psiquiátricos: [histórico]. Uso de substâncias: [descrição]. Exame do estado mental com [humor, afeto, pensamento, percepção, insight]. Hipóteses diagnósticas iniciais: [hipóteses]. Plano terapêutico inicial: [conduta].','queixa principal, início dos sintomas, histórico psiquiátrico, exame mental, hipótese diagnóstica, plano terapêutico','psiquiatria, anamnese, consulta inicial, saúde mental',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7229,1,'psiquiatria','evolucao','Evolução psiquiátrica ambulatorial','Paciente retorna em acompanhamento, referindo [evolução dos sintomas], adesão [boa, parcial ou baixa] ao tratamento e presença de [efeitos colaterais ou benefícios]. No exame psíquico atual apresenta [humor, afeto, pensamento, percepção e insight]. Avaliado risco atual de autoagressão e heteroagressão como [descrição]. Mantida ou ajustada conduta com [medicações, psicoterapia, encaminhamentos] e retorno em [prazo].','evolução dos sintomas, adesão terapêutica, exame psíquico, avaliação de risco, conduta, retorno','psiquiatria, evolução, retorno, estabilização',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7231,1,'psiquiatria','orientacao','Orientações de segurança e adesão em psiquiatria','Orientado paciente e rede de apoio quanto ao uso correto das medicações, risco de interrupção sem supervisão, higiene do sono, redução de álcool e outras substâncias e sinais de alerta para retorno imediato, incluindo piora importante do humor, ideação suicida, agitação intensa, insônia grave ou sintomas psicóticos.','medicação, rede de apoio, higiene do sono, substâncias, sinais de alerta','psiquiatria, orientação, segurança, adesão',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7233,1,'pediatria','anamnese','Anamnese pediátrica para queixa aguda','Paciente pediátrico acompanhado por [responsável], com queixa principal de [queixa], iniciada há [tempo]. Associado a [febre, tosse, vômitos, diarreia, irritabilidade ou outros sintomas]. Alimentação e hidratação em [estado]. Diurese e evacuações [descrição]. Vacinação [em dia, incompleta ou pendente]. Antecedentes relevantes: [alergias, prematuridade, doenças prévias, medicações]. Exame físico direcionado com [achados]. Conduta inicial: [conduta].','responsável, queixa aguda, febre, alimentação, hidratação, vacinação, exame físico, conduta','pediatria, anamnese, urgência leve, consulta infantil',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7235,1,'pediatria','evolucao','Evolução de puericultura e desenvolvimento','Criança em consulta de seguimento, com crescimento em [faixa esperada ou observação], desenvolvimento neuropsicomotor [adequado ou descrição], alimentação [descrição], sono [descrição] e vacinação [situação]. Exame físico sem ou com [achados]. Reforçadas orientações sobre prevenção, rotina, estímulos e retorno em [prazo].','crescimento, desenvolvimento, alimentação, sono, vacinação, exame físico, retorno','pediatria, evolução, puericultura, acompanhamento',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7237,1,'pediatria','orientacao','Orientações ao responsável e sinais de alarme pediátricos','Responsável orientado quanto à hidratação frequente, controle de temperatura conforme peso e idade, uso correto das medicações prescritas, manutenção da alimentação conforme tolerância e observação de sinais de alarme. Retornar imediatamente em caso de prostração, dificuldade respiratória, recusa hídrica persistente, convulsão, sonolência excessiva, piora clínica ou febre prolongada.','hidratação, antitérmico, alimentação, dificuldade respiratória, sinais de alarme','pediatria, orientação, responsável, sinais de alarme',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7239,1,'ginecologia_obstetricia','anamnese','Anamnese ginecológica ou obstétrica inicial','Paciente em atendimento de [ginecologia, obstetrícia, pré-natal ou puerpério], com queixa principal de [queixa]. História gineco-obstétrica: DUM [data], G/P/A [descrição], método contraceptivo [descrição], ciclos menstruais [descrição]. Relata [sangramento, corrimento, dor pélvica, movimentação fetal ou outros sintomas]. Antecedentes pessoais e cirúrgicos: [histórico]. Exame físico ou ginecológico com [achados]. Hipótese diagnóstica inicial e plano: [conduta].','tipo de atendimento, DUM, GPA, queixa, sangramento, dor pélvica, exame físico, conduta','ginecologia, obstetrícia, anamnese, pré-natal',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7241,1,'ginecologia_obstetricia','evolucao','Evolução de retorno ginecológico ou pré-natal','Paciente em seguimento, relatando [evolução clínica]. Exames recentes: [descrição]. Mantém ou não [sangramento, corrimento, dor, contrações, movimentação fetal]. Ao exame, apresenta [achados]. Mantidas ou ajustadas orientações, terapêutica e calendário de exames. Próximo retorno programado para [prazo].','evolução clínica, exames recentes, sintomas, exame, terapêutica, calendário de exames, retorno','ginecologia, obstetrícia, evolução, retorno',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7243,1,'ginecologia_obstetricia','orientacao','Orientações e sinais de alerta em ginecologia e obstetrícia','Orientada quanto a uso correto da medicação prescrita, adesão aos exames solicitados, hábitos de vida saudáveis, sinais de alerta e necessidade de retorno precoce. Procurar assistência imediatamente em caso de sangramento importante, perda de líquido, febre, dor intensa, diminuição de movimentos fetais, cefaleia forte, escotomas, piora importante do quadro ou mal-estar persistente.','medicação, exames, hábitos saudáveis, sangramento, perda de líquido, movimentos fetais, sinais de alerta','ginecologia, obstetrícia, orientação, sinais de alerta',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7245,1,'ortopedia_traumatologia','anamnese','Anamnese ortopédica para dor ou trauma','Paciente com queixa principal de [dor ou limitação], localizada em [região anatômica], com lateralidade [direita, esquerda, bilateral]. Início há [tempo], com mecanismo de trauma ou sobrecarga [descrição]. Dor em escala [0 a 10], piora com [fatores] e melhora com [fatores]. Refere limitação funcional em [atividade]. Exame direcionado com [inspeção, amplitude, força, testes especiais, estado neurovascular]. Hipótese inicial e conduta: [conduta].','região anatômica, lateralidade, mecanismo de trauma, escala de dor, limitação funcional, exame físico, conduta','ortopedia, traumatologia, anamnese, dor musculoesquelética',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7247,1,'ortopedia_traumatologia','evolucao','Evolução ortopédica com reavaliação funcional','Paciente em seguimento por [lesão ou dor], relatando evolução [melhora, estabilidade ou piora]. Mantém dor em intensidade [escala], limitação em [atividade] e adesão [descrição] ao tratamento. Exame atual demonstra [amplitude de movimento, edema, força, testes]. Exames complementares: [descrição]. Mantida ou ajustada conduta com [analgesia, imobilização, fisioterapia, infiltração, encaminhamento] e retorno em [prazo].','evolução da dor, limitação, adesão ao tratamento, exame atual, exames complementares, conduta','ortopedia, evolução, reavaliação, funcionalidade',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7249,1,'ortopedia_traumatologia','orientacao','Orientações de proteção articular e retorno ortopédico','Orientado quanto a repouso relativo, uso correto de órtese ou imobilização quando indicada, analgesia conforme prescrição, gelo ou calor conforme fase clínica, progressão segura das atividades e início ou continuidade de reabilitação. Retornar imediatamente em caso de deformidade, piora importante da dor, febre, perda de força, alteração neurovascular distal ou incapacidade funcional acentuada.','repouso relativo, imobilização, analgesia, reabilitação, perda de força, sinais de alarme','ortopedia, orientação, reabilitação, proteção articular',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7251,1,'cardiologia','anamnese','Anamnese cardiológica inicial','Paciente em avaliação cardiológica por [dor torácica, dispneia, palpitações, síncope, hipertensão ou outro motivo]. Fatores de risco: [hipertensão, diabetes, dislipidemia, tabagismo, obesidade, história familiar]. Sintomas iniciados há [tempo], com impacto em [esforço, repouso, sono]. Medicações em uso: [descrição]. Exame físico cardiovascular com [achados], PA [valor], FC [valor]. Exames prévios: [ECG, ECO, MAPA, Holter, laboratoriais]. Hipótese diagnóstica e plano: [conduta].','motivo da consulta, fatores de risco, medicações, exame físico, PA, FC, exames prévios, conduta','cardiologia, anamnese, risco cardiovascular, consulta inicial',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7253,1,'cardiologia','evolucao','Evolução de seguimento cardiológico','Paciente retorna em seguimento por [diagnóstico], com sintomas atuais [descrição]. Refere adesão [boa, parcial ou baixa] às medicações e medidas não farmacológicas. Traz controle domiciliar de pressão ou frequência com [resultados]. Exames recentes mostram [achados]. Mantidas ou ajustadas medicações, metas terapêuticas e plano de reavaliação em [prazo].','diagnóstico, sintomas atuais, adesão, controle pressórico, exames recentes, metas terapêuticas, retorno','cardiologia, evolução, hipertensão, seguimento',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7255,1,'cardiologia','orientacao','Orientações de controle cardiovascular domiciliar','Orientado quanto ao uso regular das medicações, redução de sal, controle de peso, prática de atividade física conforme liberação clínica, cessação do tabagismo e monitorização domiciliar de pressão arterial quando indicada. Retornar com exames e diário pressórico. Procurar urgência em caso de dor torácica persistente, dispneia importante, síncope, palpitações intensas ou piora súbita do estado geral.','medicação regular, redução de sal, peso, atividade física, diário pressórico, dor torácica, dispneia','cardiologia, orientação, hipertensão, prevenção',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES
(7257,1,'oftalmologia','anamnese','Anamnese oftalmológica inicial','Paciente com queixa visual principal de [baixa visual, olho vermelho, ardor, secreção, trauma ou outro], acometendo [OD, OE ou OU], iniciada há [tempo]. Relata ou nega [dor ocular, fotofobia, trauma, visão borrada, halos]. Antecedentes oftalmológicos: [cirurgias, uso de óculos, colírios, doenças prévias]. Exame inicial com [acuidade visual, biomicroscopia, tonometria, fundoscopia ou outros achados]. Hipótese e conduta: [conduta].','queixa visual, lateralidade, dor ocular, fotofobia, trauma, antecedentes, acuidade visual, conduta','oftalmologia, anamnese, baixa visual, consulta inicial',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7259,1,'oftalmologia','evolucao','Evolução oftalmológica ambulatorial','Paciente em retorno por [diagnóstico ou queixa], relatando evolução [descrição] após uso de [tratamento]. Acuidade visual atual [descrição]. Exame ocular com [achados]. Exames complementares ou refração: [descrição]. Mantida ou ajustada conduta com [lubrificação, antibiótico, correção óptica, investigação adicional] e retorno em [prazo].','diagnóstico, tratamento, acuidade visual, exame ocular, refração, conduta, retorno','oftalmologia, evolução, retorno, seguimento',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7261,1,'oftalmologia','orientacao','Orientações oftalmológicas e sinais de urgência','Orientado quanto ao uso correto dos colírios, higiene ocular, evitar automedicação e manipulação excessiva dos olhos, além de respeitar o retorno programado. Procurar avaliação urgente em caso de perda visual súbita, dor intensa, trauma ocular, secreção importante, fotofobia acentuada, piora rápida dos sintomas ou suspeita de corpo estranho.','colírio, higiene ocular, automedicação, perda visual súbita, dor intensa, trauma ocular','oftalmologia, orientação, colírio, urgência',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7263,1,'neurologia','anamnese','Anamnese neurológica inicial','Paciente em avaliação neurológica por [cefaleia, tontura, parestesia, crise, tremor, déficit motor, alteração de memória ou outro sintoma]. Início há [tempo], frequência [descrição] e fatores desencadeantes [descrição]. Sintomas associados: [náuseas, aura, alteração visual, fraqueza, dormência, alteração da fala]. Antecedentes relevantes e medicações em uso: [descrição]. Exame neurológico com [achados]. Hipótese diagnóstica inicial e plano de investigação ou tratamento: [conduta].','sintoma neurológico, início, frequência, gatilhos, sintomas associados, exame neurológico, conduta','neurologia, anamnese, cefaleia, consulta inicial',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7265,1,'neurologia','evolucao','Evolução neurológica de seguimento','Paciente retorna em seguimento por [diagnóstico ou síndrome], referindo evolução [melhora, estabilidade ou piora] dos sintomas. Mantém episódios de [cefaleia, crise, tontura, parestesia ou outro] com frequência [descrição]. Exames recentes: [RM, TC, EEG, ENMG ou outros]. Exame neurológico atual com [achados]. Mantido ou ajustado plano terapêutico, orientações e reavaliação em [prazo].','diagnóstico, evolução dos sintomas, frequência, exames recentes, exame neurológico, plano terapêutico','neurologia, evolução, seguimento, retorno',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7267,1,'neurologia','orientacao','Orientações neurológicas e sinais de alarme','Orientado quanto ao uso correto das medicações, manutenção de diário de sintomas quando aplicável, cuidados com sono, hidratação e gatilhos individuais. Procurar atendimento imediato em caso de déficit neurológico súbito, alteração de fala, convulsão prolongada, cefaleia explosiva, rebaixamento do nível de consciência, febre associada a rigidez de nuca ou piora abrupta do quadro.','medicação, diário de sintomas, sono, hidratação, déficit neurológico súbito, cefaleia explosiva','neurologia, orientação, sinais de alarme, crise',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7291,1,'medico','evolucao','Evolução clínica geral de seguimento','Motivo do acompanhamento: [descrição]. Evolução desde a última consulta: [relato]. Adesão e efeitos adversos: [avaliação]. Exame físico e resultados disponíveis: [achados]. Avaliação dos problemas ativos: [descrição]. Conduta discutida: [plano]. Orientações e retorno: [registro].','evolução, problemas ativos, adesão, exame físico, resultados, conduta, retorno','clínica médica, evolução, acompanhamento',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7293,1,'medico','orientacao','Orientações clínicas gerais individualizadas','Plano acordado com o paciente: [descrição]. Registrar orientações efetivamente fornecidas sobre [uso de medicamentos prescritos, autocuidado e acompanhamento]. Sinais de alerta específicos do caso e local de atendimento: [descrição]. Exames e retorno: [prazos]. Dúvidas e compreensão do paciente: [registro].','plano, autocuidado, medicamentos, sinais de alerta, retorno, compreensão','clínica médica, orientação, autocuidado',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7295,1,'dentista','anamnese','Anamnese odontológica inicial','Queixa odontológica: [descrição]. História da dor ou desconforto: [localização, duração e fatores associados]. Antecedentes odontológicos e clínicos: [descrição]. Alergias, medicamentos e condições relevantes: [registro]. Exame extraoral e intraoral: [achados]. Dentes e superfícies envolvidos: [notação FDI]. Avaliação e plano proposto: [descrição].','queixa, dor, antecedentes, alergias, exame intraoral, dentes, avaliação, plano','odontologia, anamnese, avaliação inicial',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7297,1,'dentista','evolucao','Evolução odontológica de tratamento','Procedimento ou acompanhamento: [descrição]. Dente, região e superfície: [notação FDI]. Achados e evolução: [registro]. Procedimento efetivamente realizado, materiais e anestesia quando aplicável: [detalhes]. Intercorrências: [descrição]. Orientações fornecidas e próxima etapa: [registro].','procedimento, dente, região, materiais, anestesia, intercorrências, retorno','odontologia, evolução, plano de tratamento',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7299,1,'dentista','orientacao','Orientações odontológicas individualizadas','Atendimento ou procedimento realizado: [descrição]. Orientações individualizadas de higiene oral, alimentação e cuidados locais: [registro]. Medicamentos apenas conforme prescrição emitida: [registro]. Sinais de alerta e canal para intercorrências: [descrição]. Revisão e continuidade do tratamento: [prazo e plano].','procedimento, higiene oral, cuidados locais, prescrição, sinais de alerta, revisão','odontologia, orientação, acompanhamento',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7301,1,'psicologia','anamnese','Entrevista psicológica inicial','Demanda e objetivos relatados: [descrição]. História e contexto da demanda: [registro]. Contexto familiar, social e ocupacional relevante: [descrição]. Acompanhamentos anteriores e atuais: [registro]. Observações clínicas: [descrição]. Avaliação de riscos e fatores de proteção, quando pertinente: [registro]. Contrato terapêutico, limites de sigilo e plano inicial: [registro].','demanda, contexto, histórico, observações, riscos, fatores de proteção, plano','psicologia, entrevista inicial, acolhimento',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7303,1,'psicologia','evolucao','Evolução de sessão psicológica','Objetivos da sessão: [descrição]. Conteúdos clinicamente relevantes e observações: [registro necessário ao acompanhamento]. Intervenções efetivamente realizadas: [descrição]. Resposta e evolução observadas: [registro]. Riscos e proteção, se pertinente: [avaliação]. Plano terapêutico e próximos passos: [descrição]. Registrar somente informações necessárias ao cuidado.','objetivos, observações, intervenções, evolução, plano terapêutico','psicologia, evolução, sessão',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7305,1,'psicologia','orientacao','Orientações e continuidade do cuidado psicológico','Orientações discutidas na sessão: [descrição]. Estratégias acordadas e atividades, quando pertinentes: [registro]. Rede de apoio e encaminhamentos pactuados: [descrição]. Plano de segurança, se indicado pela avaliação: [registro]. Em situação de risco imediato, buscar serviço de urgência. Continuidade do acompanhamento: [prazo].','orientações, estratégias, rede de apoio, encaminhamentos, segurança, retorno','psicologia, orientação, continuidade do cuidado',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
