INSERT INTO `planos_cuidado` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`tema`,`titulo`,`objetivo`,`metas`,`conduta`,`frequencia_retorno`,`proxima_revisao`,`status`,`indicadores`,`orientacoes`,`criado_em`,`atualizado_em`) VALUES
(7401,1,2004,204,'psiquiatria','Plano de seguimento do humor e sono','Reduzir sintomas depressivos e melhorar higiene do sono.','- Reavaliar humor e energia em 15 dias\n- Monitorar adesão ao antidepressivo\n- Revisar rotina de sono','Ajuste farmacológico, psicoeducação e rastreio de risco em cada retorno.','quinzenal','2026-05-27','em_acompanhamento','PHQ-9, qualidade do sono, adesão medicamentosa','Manter rotina regular de sono e buscar suporte se houver piora aguda.','2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7402,1,2006,206,'ginecologia_obstetricia','Plano de cuidado pré-natal habitual','Manter gestação de baixo risco com seguimento adequado.','- Realizar exames do trimestre\n- Acompanhar ganho ponderal\n- Revisar sinais de alerta obstétricos','Consultas periódicas, suplementação e educação em saúde.','mensal','2026-06-09','ativo','PA, BCF, peso materno, exames laboratoriais','Retornar antes em caso de sangramento, redução de movimentos fetais ou cefaleia persistente.','2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7403,1,2008,208,'cardiologia','Controle pressórico e investigação de palpitações','Melhorar controle da pressão arterial e concluir estratificação cardiovascular.','- Monitorar PA domiciliar\n- Realizar ECG, eco e Holter\n- Reforçar adesão ao tratamento','Ajuste antihipertensivo, exame complementar e revisão de estilo de vida.','30 dias','2026-06-12','ativo','PA média, FC, sintomas de palpitação, exames realizados','Evitar automedicação e procurar atendimento se dor torácica ou dispneia importante.','2026-11-11 23:52:13','2026-11-11 23:52:13'),
(7404,1,2010,210,'neurologia','Seguimento de cefaleia com aura','Reduzir frequência das crises e excluir causas secundárias.','- Preencher diário de cefaleia\n- Realizar RM de crânio\n- Revisar resposta ao tratamento','Profilaxia medicamentosa, educação sobre gatilhos e revisão com exames.','30 dias','2026-06-12','ativo','Frequência das crises, intensidade, sintomas neurológicos associados','Procurar urgência se ocorrer déficit focal persistente ou alteração do nível de consciência.','2026-11-11 23:52:13','2026-11-11 23:52:13');
