INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES
(1,1,1,201,1,'2026-05-05 09:15:00','Hipertensa há 5 anos, em uso de losartana 50mg/dia. Refere sedentarismo parcial.','Cefaleia leve e necessidade de revisão de medicação.','PA 148x92 mmHg, FC 78 bpm, sem sinais de alarme.','Hipertensão arterial sistêmica sem controle ideal.','Reforçadas medidas não farmacológicas e aumento de seguimento. Mantida losartana e solicitado MAPA se persistência.','Paciente compreendeu orientação e retornará em 15 dias.','Preferir consultas pela manhã.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(2,1,2,201,2,'2026-05-06 10:10:00','DM2 em uso irregular de metformina. Dieta com alto teor de carboidrato.','Cansaço, sede aumentada e oscilação glicêmica.','IMC 31, glicemia capilar 212 mg/dL.','Diabetes mellitus tipo 2 descompensado.','Solicitados exames laboratoriais completos, reforço dietético e retorno em 7 dias.','Motivado a aderir melhor ao tratamento.','Necessita acompanhamento multiprofissional.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(3,1,3,201,3,'2026-05-07 15:10:00','Histórico de rinite alérgica e sinusite de repetição.','Congestão nasal residual após tratamento.','Sem febre, saturação normal, fala em frases completas.','Sinusite aguda em melhora clínica.','Manter lavagem nasal, hidratação e finalizar medicação prescrita anteriormente.','Boa resposta terapêutica; liberada para atividades habituais.','Teleconsulta concluída sem intercorrências.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(4,1,5,202,5,'2026-05-08 14:10:00','Paciente sem comorbidades, escovação 2x ao dia, uso irregular de fio dental.','Sensibilidade em molar superior direito.','Lesão de cárie em elemento 16, biofilme supragengival leve.','Cárie dentária em esmalte/dentina no elemento 16.','Indicada restauração em resina, orientação de higiene e profilaxia.','Paciente aceitou plano de tratamento proposto.','Solicitada radiografia bite-wing se sensibilidade persistir.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5,1,4,201,4,'2026-05-12 08:50:00','Dislipidemia em uso de sinvastatina 20mg. Sem dor torácica.','Retorno com exames de rotina.','PA 128x80 mmHg, LDL ainda acima da meta.','Dislipidemia mista com resposta parcial ao tratamento.','Ajustado tratamento e mantido acompanhamento trimestral.','Evolução estável.','Reforçada adesão à dieta e caminhada.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(6,1,7,202,7,'2026-05-17 09:20:00','Paciente pediátrica com rinite alérgica, boa colaboração em consultório.','Consulta preventiva odontológica.','Placa bacteriana leve e inflamação gengival discreta.','Gengivite leve associada à higiene insuficiente.','Profilaxia, aplicação tópica de flúor e reforço educativo para responsável.','Sem dor, procedimento bem tolerado.','Retorno preventivo em 6 meses.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5001,1,2001,201,4001,'2026-05-12 09:10:00','Paciente comparece para check-up anual, refere sedentarismo parcial e controle irregular da pressão.','Deseja avaliação geral, revisão de exames e ajuste de hábitos.','Bom estado geral, hidratado, PA 138x86 mmHg, FC 78 bpm, ausculta cardíaca e pulmonar sem alterações relevantes.','Hipertensão estágio 1 em acompanhamento; sobrepeso; dislipidemia em investigação.','Solicitados exames laboratoriais, reforço de dieta hipossódica e atividade física regular.','Paciente orientado e concordante com mudanças de estilo de vida.','Retorno em 30 dias com exames.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5002,1,2002,202,4002,'2026-05-12 10:10:00','Paciente relata sangramento gengival esporádico e sensibilidade em molar superior direito.','Avaliação odontológica inicial e limpeza.','Biofilme moderado, gengivite leve e restauração antiga infiltrada em 16.','Gengivite associada a biofilme e suspeita de infiltração em restauração.','Profilaxia, orientação de higiene, radiografia interproximal e planejamento restaurador.','Boa compreensão e adesão às orientações.','Retorno para restauração e reavaliação periodontal.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5003,1,2003,203,4003,'2026-05-12 11:05:00','Paciente em seguimento psicológico por ansiedade, preocupação excessiva e perfeccionismo no trabalho.','Ansiedade, autocobrança e ruminação.','Sem exame físico aplicável; apresentação compatível com bom autocuidado.','Sintomas ansiosos com prejuízo leve a moderado no funcionamento ocupacional.','Psicoeducação, identificação de gatilhos e treino inicial de respiração diafragmática.','Paciente engajada, verbaliza alívio após reestruturação cognitiva inicial.','Manter registro de pensamentos automáticos.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5004,1,2004,204,4004,'2026-05-12 13:05:00','Paciente com histórico de humor deprimido, insônia terminal e queda de energia há cerca de 5 meses.','Humor deprimido, irritabilidade e insônia.','Estado geral preservado, sem alterações neurológicas focais observáveis na consulta.','Episódio depressivo em investigação; transtorno ansioso associado.','Ajuste de antidepressivo, orientação de higiene do sono e avaliação de risco.','Paciente consciente, crítico, sem sinais psicóticos no momento.','Retorno em 15 dias.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5005,1,2005,205,4005,'2026-05-12 14:05:00','Mãe refere febre há 2 dias, coriza e tosse seca, com redução leve do apetite.','Febre e sintomas respiratórios altos.','Afebril no momento após antitérmico, orofaringe hiperemiada leve, ausculta pulmonar sem ruídos adventícios.','Infecção viral de vias aéreas superiores.','Medidas de suporte, hidratação, controle térmico e sinais de alarme.','Criança ativa, hidratada e sem desconforto respiratório.','Retorno se persistência da febre ou piora clínica.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5006,1,2006,206,4006,'2026-05-12 15:05:00','Gestante G2P1A0, 24 semanas, sem queixas relevantes, boa aceitação alimentar e movimentação fetal presente.','Retorno de pré-natal.','PA 110x70 mmHg, peso adequado para a idade gestacional, BCF presente, sem edema.','Gestação de baixo risco em evolução habitual.','Manter suplementação, solicitar exames de rotina do trimestre e reforçar sinais de alerta.','Paciente orientada e tranquila.','Retorno em 4 semanas.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5007,1,2007,207,4007,'2026-05-12 16:05:00','Dor em joelho direito há 3 semanas, piora ao correr e subir escadas, sem trauma direto importante.','Dor no joelho direito.','Dor à palpação patelofemoral, sem derrame importante, arco preservado com desconforto no agachamento.','Síndrome dolorosa femoropatelar; tendinopatia associada a sobrecarga.','Analgesia, redução temporária do impacto e encaminhamento para fisioterapia.','Paciente entende necessidade de ajuste do treino.','Retorno em 21 dias.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5008,1,2008,208,4008,'2026-05-13 09:05:00','Paciente hipertensa, com palpitações episódicas e dispneia aos médios esforços.','Palpitações e avaliação de risco cardiovascular.','PA 146x88 mmHg, FC 84 bpm, sem edema, bulhas normofonéticas.','Hipertensão arterial sistêmica; palpitações em investigação; risco CV intermediário/alto.','Solicitados ECG, ecocardiograma e Holter; ajuste de antihipertensivo e metas pressóricas.','Paciente compreende necessidade de estratificação.','Retorno com exames.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5009,1,2009,209,4009,'2026-05-13 10:05:00','Paciente com baixa visual progressiva e dificuldade para leitura noturna, nega trauma ocular.','Visão embaçada e cansaço visual.','Sem hiperemia importante; acuidade reduzida sem correção em ambos os olhos.','Erro refracional associado a suspeita de catarata inicial.','Atualização de refração, orientação e solicitação de exames complementares.','Paciente orientado sobre acompanhamento seriado.','Revisão após exames e adaptação de correção óptica.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5010,1,2010,210,4010,'2026-05-13 11:05:00','Paciente refere cefaleia pulsátil recorrente, parestesias transitórias em membro superior esquerdo e fotofobia.','Cefaleia e parestesias.','Sem déficit focal fixo na consulta, marcha preservada, fala sem alterações.','Enxaqueca com aura em investigação diferencial; necessidade de exclusão de outras causas neurológicas.','Solicitada RM de crânio, ajuste de profilaxia e diário de cefaleia.','Paciente sem sinais de alarme no momento.','Retorno em 30 dias ou antes se piora.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5011,1,2011,201,4011,'2026-07-01 09:00:10','Paciente em consulta de seguimento preventivo, com revisão de hábitos, rotina de exames e fatores de risco metabólico.','Deseja avaliação clínica geral e orientação de prevenção.','Bom estado geral, sinais vitais estáveis e sem alterações agudas relevantes ao exame físico.','Acompanhamento preventivo; necessidade de reforço em hábitos de vida e controle laboratorial.','Solicitados exames de rotina, reforçadas orientações sobre alimentação, sono e atividade física.','Paciente aderente e concordante com retorno programado.','Retorno com exames em prazo habitual.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5012,1,2013,202,4014,'2026-07-01 10:00:10','Paciente refere sensibilidade localizada e interesse em revisão odontológica preventiva.','Sensibilidade dentária e necessidade de avaliação bucal.','Biofilme leve a moderado, restaurações prévias íntegras exceto ponto suspeito em molar.','Cárie inicial / necessidade de acompanhamento periodontal preventivo.','Orientação de higiene, profilaxia e planejamento restaurador conforme exame clínico.','Boa aceitação do plano terapêutico proposto.','Agendado retorno para execução e reavaliação.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5013,1,2015,203,4017,'2026-07-02 11:00:10','Paciente busca atendimento por sobrecarga emocional, ansiedade e dificuldade de organização da rotina.','Ansiedade, estresse e autocobrança.','Apresentação adequada, discurso coerente e contato preservado.','Sintomas ansiosos com impacto funcional leve a moderado.','Psicoeducação, acolhimento, identificação de gatilhos e proposta de acompanhamento.','Paciente engajado e disposto a manter registro entre sessões.','Manter seguimento semanal e tarefas entre sessões.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5014,1,2017,204,4020,'2026-07-02 13:30:10','Paciente em avaliação por humor deprimido, insônia e oscilação de energia nas últimas semanas.','Humor deprimido, ansiedade e sono não reparador.','Estado mental sem sinais psicóticos, crítica preservada e sem risco agudo identificado.','Transtorno ansioso/depressivo em investigação e seguimento.','Ajuste terapêutico inicial, higiene do sono e orientação sobre sinais de alerta.','Paciente compreende plano e aceita acompanhamento próximo.','Retorno breve para reavaliação de resposta clínica.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5015,1,2019,205,4023,'2026-07-03 14:30:10','Consulta de puericultura/seguimento, com revisão de crescimento, alimentação e marcos de desenvolvimento.','Rotina pediátrica e orientações preventivas.','Criança ativa, hidratada, sem sinais de toxemia ou desconforto respiratório.','Seguimento pediátrico sem intercorrências maiores no momento.','Orientações de sono, alimentação, vacinação e sinais de alerta aos responsáveis.','Responsável orientado e sem dúvidas ao final da consulta.','Programado retorno conforme faixa etária ou antes se necessidade.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5016,1,2021,206,4026,'2026-07-03 15:30:10','Paciente comparece para rotina ginecológica / seguimento com foco em prevenção e sintomas do ciclo.','Avaliação ginecológica preventiva.','Sem alterações agudas; exame clínico compatível com seguimento ambulatorial.','Seguimento ginecológico habitual; rastreio e acompanhamento conforme faixa etária.','Solicitados exames preventivos e reforçadas orientações sobre sinais de alerta.','Paciente acolhida, esclarecida e concordante com conduta.','Retorno programado após exames ou conforme necessidade clínica.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5017,1,2023,207,4029,'2026-07-04 09:00:10','Paciente com dor osteomuscular relacionada a esforço repetitivo / atividade física.','Dor articular e limitação funcional leve.','Dor à mobilização específica, sem sinais inflamatórios sistêmicos ou déficit neurovascular.','Síndrome dolorosa musculoesquelética por sobrecarga / inflamação local.','Analgesia, orientação funcional, ajuste de carga e encaminhamento para fisioterapia se indicado.','Paciente compreende medidas de proteção e retorno programado.','Monitorar resposta clínica e necessidade de imagem complementar.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5018,1,2025,208,4032,'2026-07-04 10:00:10','Paciente em reavaliação cardiológica por controle pressórico, dispneia ou palpitações intermitentes.','Controle cardiovascular e revisão de risco.','PA em faixa limítrofe, ausculta sem achados agudos e sem edema periférico.','Risco cardiovascular em seguimento, com necessidade de rastreio complementar conforme quadro.','Reforçadas metas pressóricas, atividade física e solicitação de exames complementares.','Paciente aderente e motivado a manter acompanhamento.','Retorno com monitorização e exames programados.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5019,1,2027,209,4035,'2026-07-05 11:00:10','Paciente refere cansaço visual, olho seco ou dificuldade progressiva para leitura.','Baixa visual / desconforto ocular.','Acuidade reduzida sem correção; segmento anterior sem intercorrências agudas.','Erro refracional / superfície ocular em avaliação, com seguimento ambulatorial.','Orientada refração, lubrificação ocular e complementação diagnóstica quando indicada.','Paciente orientado sobre acompanhamento seriado.','Retorno após exames e adaptação de conduta óptica.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(5020,1,2029,210,4038,'2026-07-05 14:00:10','Paciente em investigação de cefaleia, tonturas ou parestesias transitórias sem sinais de alarme atuais.','Cefaleia recorrente / sintomas neurológicos intermitentes.','Sem déficit focal fixo ao exame clínico nesta consulta.','Cefaleia primária / quadro neurológico em investigação diferencial.','Solicitados exames conforme quadro, diário de sintomas e orientação sobre sinais de urgência.','Paciente compreende necessidade de monitorização e retorno.','Revisão com exames e avaliação de resposta terapêutica.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `protocolos_clinicos` (`id`,`empresa_id`,`tema`,`titulo`,`categoria`,`objetivo`,`checklist`,`criterios`,`orientacoes`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES
(7101,1,'psiquiatria','Acolhimento inicial em risco psíquico','Risco','Padronizar acolhimento, estratificação e encaminhamento de pacientes com sofrimento psíquico agudo.','- Confirmar queixa principal e fator precipitante\n- Avaliar ideação suicida, plano e meios\n- Revisar suporte familiar e rede de proteção\n- Definir necessidade de observação/encaminhamento','Priorizar se risco suicida moderado/alto, agitação importante, psicose desorganizada ou ausência de suporte.','Registrar plano de segurança, orientar sinais de alerta e documentar responsável quando aplicável.','risco, urgência, psiquiatria',1,204,204,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7102,1,'pediatria','Febre sem sinais de toxemia','Retorno','Organizar avaliação e orientação domiciliar nos quadros febris de baixa complexidade.','- Confirmar duração da febre\n- Checar hidratação, aceitação alimentar e diurese\n- Revisar vacinação\n- Informar sinais de alarme','Reavaliar rapidamente se prostração, desconforto respiratório, sonolência excessiva ou febre persistente.','Entregar orientação escrita de hidratação, controle térmico e retorno programado.','pediatria, febre, sinais de alarme',1,205,205,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7103,1,'cardiologia','Seguimento ambulatorial de hipertensão','Seguimento','Padronizar consulta de revisão pressórica e adesão ao tratamento.','- Conferir pressão arterial e frequência cardíaca\n- Revisar adesão medicamentosa\n- Checar eventos adversos\n- Solicitar exames conforme risco','Escalonar investigação se PA persistentemente elevada, sintomas de isquemia ou sinais de lesão de órgão-alvo.','Reforçar metas pressóricas, atividade física e retorno com monitorização domiciliar quando possível.','hipertensão, cardiologia, risco cardiovascular',1,208,208,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7104,1,'neurologia','Cefaleia com sinais de atenção','Triagem','Apoiar triagem clínica de cefaleias com necessidade de investigação complementar.','- Caracterizar padrão da dor\n- Revisar déficits focais e alterações visuais\n- Checar uso prévio de analgesia\n- Definir necessidade de neuroimagem','Encaminhar urgência se déficit focal persistente, cefaleia explosiva, febre com rigidez de nuca ou rebaixamento do nível de consciência.','Orientar diário de sintomas, gatilhos e retorno com exames solicitados.','cefaleia, neurologia, red flags',1,210,210,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7105,1,'medico','Check-up clínico e prevenção cardiometabólica','Prevenção','Padronizar atendimento clínico preventivo com foco em fatores de risco, exames de rotina e orientação de estilo de vida.','- Revisar antecedentes pessoais e familiares\n- Avaliar pressão arterial, IMC e circunferência abdominal\n- Solicitar/checar exames laboratoriais periódicos\n- Reforçar plano de prevenção e retorno','Priorizar seguimento se houver hipertensão, obesidade, diabetes, tabagismo ou alterações laboratoriais relevantes.','Orientar alimentação, atividade física, sono, cessação do tabagismo e retorno com exames conforme risco.','clinica medica, prevenção, check-up',1,201,201,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7106,1,'dentista','Avaliação inicial com risco de cárie e periodontal','Triagem','Organizar avaliação odontológica inicial com estratificação de risco, higiene oral e definição do plano terapêutico.','- Identificar queixa principal e dor\n- Avaliar biofilme, sangramento gengival e lesões cariosas\n- Definir necessidade de radiografias\n- Registrar plano imediato e retorno','Antecipar intervenção se dor espontânea, abscesso, sangramento persistente, mobilidade dentária ou suspeita de infecção.','Reforçar técnica de higiene oral, controle de dieta cariogênica e cronograma de tratamento por etapas.','odontologia, cárie, periodontal, triagem',1,202,202,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7107,1,'psicologia','Acolhimento inicial e definição de plano terapêutico','Acolhimento','Padronizar entrevista inicial, mapeamento de demandas, fatores precipitantes e objetivos terapêuticos.','- Identificar demanda principal e contexto atual\n- Levantar história emocional, familiar e ocupacional\n- Avaliar risco psíquico e rede de apoio\n- Definir objetivo inicial e frequência sugerida','Priorizar encaminhamento compartilhado se houver risco de autoagressão, sintomas graves ou prejuízo funcional importante.','Registrar contrato terapêutico, combinados de acompanhamento e indicadores de evolução clínica.','psicologia, acolhimento, plano terapêutico',1,203,203,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7108,1,'ginecologia_obstetricia','Rastreamento ginecológico e seguimento pré-natal habitual','Seguimento','Padronizar consulta preventiva ginecológica e o acompanhamento obstétrico de rotina com foco em sinais de alerta.','- Revisar queixas, ciclo menstrual e histórico obstétrico\n- Conferir exames preventivos e laboratoriais\n- Avaliar sinais de alerta ginecológicos/obstétricos\n- Definir retorno e exames complementares','Escalonar rapidamente se houver sangramento anormal, dor intensa, hipertensão gestacional, redução de movimentos fetais ou sinais infecciosos.','Orientar adesão ao pré-natal, exames periódicos, vacinação e retorno imediato diante de sinais de alerta.','ginecologia, obstetricia, pré-natal, rastreio',1,206,206,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7109,1,'ortopedia_traumatologia','Dor osteomuscular sem trauma grave','Conduta inicial','Padronizar abordagem de dor musculoesquelética ambulatorial com avaliação funcional, analgesia e indicação de imagem.','- Localizar dor e mecanismo de sobrecarga/trauma\n- Avaliar amplitude de movimento e sinais inflamatórios\n- Identificar necessidade de raio-X/USG/RM\n- Definir proteção articular e reabilitação','Encaminhar urgência se houver deformidade, déficit neurovascular, incapacidade de apoio, febre ou suspeita de fratura/agressão articular importante.','Orientar repouso relativo, analgesia, gelo/calor conforme caso e retorno para reavaliação funcional.','ortopedia, trauma, dor musculoesquelética',1,207,207,'2026-11-11 23:52:12','2026-11-11 23:52:12'),
(7110,1,'oftalmologia','Triagem de baixa visual e olho vermelho','Triagem','Organizar avaliação inicial de queixas visuais frequentes, identificando sinais de gravidade e necessidade de investigação rápida.','- Avaliar acuidade visual e lateralidade da queixa\n- Investigar dor, secreção, fotofobia e trauma\n- Medir pressão intraocular quando indicado\n- Definir necessidade de exame complementar e retorno','Priorizar urgência se perda visual súbita, trauma ocular, dor intensa, fotofobia importante, secreção purulenta ou suspeita de glaucoma agudo.','Orientar evitar automedicação ocular, manter acompanhamento e retornar imediatamente se houver piora dos sintomas.','oftalmologia, baixa visual, olho vermelho, triagem',1,209,209,'2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `psicologia_escalas` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`nome_escala`,`score_total`,`classificacao`,`data_aplicacao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES
(1,1,3,203,'GAD-7','14/21','Ansiedade moderada','2026-05-10','Aplicação inicial em contexto de queixa ansiosa e dificuldade de sono.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(2,1,6,203,'PHQ-9','9/27','Sintomas leves a moderados','2026-05-18','Paciente relatou estresse ocupacional e irritabilidade.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(6301,1,2003,203,'GAD-7','12','Ansiedade moderada','2026-05-12','Escala aplicada na primeira fase do acompanhamento.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `psicologia_planos` (`id`,`empresa_id`,`prontuario_id`,`paciente_id`,`profissional_id`,`abordagem`,`demanda_focal`,`objetivo_principal`,`metas`,`metas_curto_prazo`,`metas_medio_prazo`,`metas_longo_prazo`,`estrategias_intervencao`,`indicadores_evolucao`,`criterios_alta`,`risco_monitorado`,`frequencia_sugerida`,`status`,`data_inicio`,`data_reavaliacao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES
(1,1,NULL,3,203,'TCC',NULL,'Reduzir sintomas ansiosos e melhorar organização emocional.','Mapear gatilhos, construir rotina de regulação emocional e reforçar autocuidado.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'semanal','ativo','2026-05-10','2026-06-10','Paciente prefere encontros híbridos e acompanha exercícios entre sessões.','2026-11-11 23:52:12','2026-11-11 23:52:12'),
(6201,1,5003,2003,203,'Terapia Cognitivo-Comportamental','Ansiedade de desempenho, perfeccionismo e ruminação.','Reduzir sintomas ansiosos e ampliar flexibilidade cognitiva.','Psicoeducação, manejo fisiológico da ansiedade, reestruturação cognitiva e treino de limites.','Identificar gatilhos e registrar pensamentos automáticos por 4 semanas.','Diminuir episódios de ansiedade intensa no trabalho e aumentar uso de técnicas de regulação.','Desenvolver rotina sustentável com menor autocobrança e melhor qualidade de vida.','Sessões semanais, tarefas entre sessões, registros cognitivos e experimentos comportamentais.','Redução de ruminação, melhora do sono, autoavaliação de ansiedade e adesão às tarefas.','Sintomas controlados, autonomia em estratégias de enfrentamento e melhora funcional sustentada.','Baixo risco, sem ideação atual; manter rastreio periódico.','Semanal','ativo','2026-05-12','2026-06-23','Plano terapêutico inicial com reavaliação em seis semanas.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `psicologia_prontuario` (`id`,`empresa_id`,`prontuario_id`,`paciente_id`,`profissional_id`,`tipo_registro`,`demanda_principal`,`historico_pessoal`,`historico_familiar`,`historico_psiquiatrico`,`uso_medicacao`,`fatores_risco`,`fatores_protecao`,`objetivo_terapeutico`,`queixa_historico`,`expectativas_tratamento`,`encaminhado_por`,`motivo_encaminhamento`,`historico_saude`,`uso_substancias`,`sono_apetite`,`suporte_rede`,`contexto_escolar_profissional`,`antecedentes_trauma_luto`,`humor_afeto`,`pensamento_linguagem`,`comportamento`,`cognicao_orientacao`,`estado_mental_aparencia`,`estado_mental_sensopercepcao`,`risco_suicida`,`risco_autoheteroagressao`,`temas_sessao`,`intervencoes_realizadas`,`tecnicas_utilizadas`,`resposta_paciente`,`adesao_processo`,`recursos_mobilizados`,`manejo_crise`,`tarefas_entre_sessoes`,`encaminhamentos`,`plano_sessao_seguinte`,`observacoes_confidenciais`,`consentimento_tipo`,`consentimento_terapia_texto`,`consentimento_tele_texto`,`consentimento_privacidade_texto`,`consentimento_compartilhamento_texto`,`consentimento_gravacao_texto`,`consentimento_terapia_aceito`,`consentimento_tele_aceito`,`consentimento_privacidade_aceito`,`consentimento_compartilhamento_aceito`,`consentimento_gravacao_aceito`,`consentimento_nome_responsavel`,`consentimento_documento`,`consentimento_parentesco`,`consentimento_testemunha`,`consentimento_registrado_em`,`criado_em`,`atualizado_em`) VALUES
(6101,1,5003,2003,203,'sessao','Ansiedade associada à autocobrança e medo de falhar no ambiente de trabalho.','Refere histórico de perfeccionismo desde adolescência e dificuldade em dizer não.','Mãe com traços ansiosos e dinâmica familiar rígida quanto a desempenho.','Acompanhamento psiquiátrico ambulatorial sem internações prévias.','Sertralina 50mg/dia.','Sobrecarga profissional, privação de sono em períodos de fechamento e autocrítica elevada.','Rede de apoio familiar e boa capacidade reflexiva.','Reduzir intensidade da ansiedade e ampliar repertório de enfrentamento.','Queixas iniciadas com intensificação das demandas no trabalho nos últimos 12 meses.','Deseja aprender a controlar a ansiedade e melhorar equilíbrio vida-trabalho.','Demanda espontânea','Busca por manejo de ansiedade e autocobrança.','Sem comorbidades clínicas relevantes relatadas.','Uso social de álcool; nega outras substâncias.','Sono irregular em semanas mais estressantes; apetite preservado.','Boa relação com irmã e amigos próximos.','Trabalho com metas agressivas e dificuldade em pausas.','Relata término afetivo importante há 2 anos ainda com impacto emocional residual.','Ansiosa, porém com afeto congruente e acesso emocional preservado.','Curso do pensamento organizado, linguagem clara e objetiva.','Cooperativa, atenta e participativa.','Orientada em tempo, espaço e pessoa.','Boa higiene e vestimenta adequada.','Sem alterações sensoperceptivas relatadas.','baixo','Nega ideação atual e história de auto/heteroagressão.','Ansiedade de desempenho, limites pessoais, rotina de descanso.','Psicoeducação, identificação de pensamentos automáticos e validação emocional.','Reestruturação cognitiva inicial e respiração diafragmática.','Refere alívio e maior clareza sobre gatilhos.','Boa adesão.','Escrita terapêutica e apoio de rede social.','Não aplicável.','Registrar situações de ansiedade e pensamentos automáticos.','Sem encaminhamentos externos neste momento.','Aprofundar crenças centrais relacionadas a desempenho.','Sem observações confidenciais adicionais.','ambos','Paciente orientada sobre objetivos, sigilo e limites do acompanhamento psicológico.','Paciente ciente das orientações para atendimentos remotos quando necessários.','Paciente informada sobre tratamento de dados pessoais e sensíveis para fins assistenciais.','Paciente autoriza compartilhamento apenas quando clinicamente necessário e com respaldo ético/legal.','Gravações somente mediante autorização específica.',1,1,1,1,0,'Paula Mendes Souza','123.456.789-03','Própria paciente','Administrador Demo','2026-05-12 11:00:00','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `psiquiatria_prontuario` (`id`,`empresa_id`,`prontuario_id`,`paciente_id`,`profissional_id`,`psiq_tipo_atendimento`,`psiq_queixa_principal`,`psiq_inicio_sintomas`,`psiq_fatores_desencadeantes`,`psiq_historico_psiquiatrico`,`psiq_internacoes_previas`,`psiq_historico_familiar`,`psiq_uso_substancias`,`psiq_comorbidades`,`psiq_humor_afeto`,`psiq_pensamento`,`psiq_percepcao`,`psiq_cognicao`,`psiq_juizo_critica`,`psiq_risco_suicidio`,`psiq_plano_seguranca`,`psiq_risco_heteroagressao`,`psiq_hipotese_diag`,`psiq_cid10`,`psiq_medicacoes`,`psiq_orientacoes_efeitos`,`psiq_psicoterapia_indicada`,`psiq_encaminhamentos`,`psiq_conduta_urgente`,`psiq_plano_retorno`,`criado_em`,`atualizado_em`) VALUES
(6401,1,5004,2004,204,'retorno','Humor deprimido, insônia e irritabilidade.','Há cerca de 5 meses, com piora progressiva.','Sobrecarga ocupacional e conflitos familiares recentes.','Acompanhamento ambulatorial prévio sem internações e sem episódios psicóticos.','Nega internações psiquiátricas prévias.','Tio com transtorno bipolar; mãe com ansiedade.','Uso social de álcool; nega outras substâncias.','Insônia e sintomas ansiosos associados.','Humor deprimido, afeto rebaixado, reativo em alguns momentos.','Curso do pensamento organizado, conteúdo com preocupação excessiva, sem delírios.','Nega alucinações.','Atenção e memória preservadas na consulta.','Crítica parcialmente preservada com boa adesão potencial.','baixo','Orientado a procurar suporte familiar, serviço de urgência e contato emergencial se piora importante ou ideação suicida.','Nega heteroagressividade.','Episódio depressivo com sintomas ansiosos associados.','F32.1','Escitalopram 10mg/noite, com possibilidade de ajuste gradual.','Orientado sobre latência terapêutica, náusea inicial, sonolência e importância de não interromper abruptamente.','sim','Manter seguimento psicológico concomitante.','Sem indicação de internação ou manejo urgente nesta consulta.','Retorno em 15 dias para reavaliação de resposta e tolerabilidade.','2026-11-11 23:52:12','2026-11-11 23:52:12');
